  const [mezziFlotta, setMezziFlotta] = useState<MezzoFlotta[]>(() => {
    try {
      const saved = localStorage.getItem('CROCE_ORO_MEZZI_FLOTTA');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
          return parsed.sort((a, b) => a.sigla.localeCompare(b.sigla, 'it', { numeric: true, sensitivity: 'base' }));
        }
      }
    } catch {}
    return [...MEZZI_FLOTTA_INIZIALI].sort((a, b) => a.sigla.localeCompare(b.sigla, 'it', { numeric: true, sensitivity: 'base' }));
  });
  const mezziFlottaRef = useRef<MezzoFlotta[]>(mezziFlotta);
  mezziFlottaRef.current = mezziFlotta;
  const handleAggiornaMezziFlotta = (nuovi: MezzoFlotta[]) => {
    const ordinati = [...nuovi].sort((a, b) => a.sigla.localeCompare(b.sigla, 'it', { numeric: true, sensitivity: 'base' }));
    mezziFlottaRef.current = ordinati;
    setMezziFlotta(ordinati);
    try {
      localStorage.setItem('CROCE_ORO_MEZZI_FLOTTA', JSON.stringify(ordinati));
    } catch {}
    realtime.syncMezziFlotta(ordinati);
  };

  const flottaSigleDinamiche = useMemo(() => {
    const sigle = new Set<string>(FLOTTA_COMPLETA);
    mezziFlotta.forEach((m) => {
      if (m?.sigla?.trim()) sigle.add(m.sigla.trim().toUpperCase());
    });
    return Array.from(sigle).sort((a, b) => a.localeCompare(b, 'it', { numeric: true, sensitivity: 'base' }));
  }, [mezziFlotta]);

