  // 4a. Magazzino Parti / Ricambi Mezzi (Tagliandi, oli, lubrificanti, lampadine, ricambi) con sincronizzazione server & recupero locale
  const [magazzinoParti, setMagazzinoParti] = useState<ArticoloMagazzinoMezzi[]>(() => {
    try {
      const recuperati = new Map<string, ArticoloMagazzinoMezzi>();
      const savedParti = localStorage.getItem('CROCE_ORO_MAGAZZINO_PARTI_MEZZI');
      if (savedParti) {
        const parsed = JSON.parse(savedParti);
        if (Array.isArray(parsed)) {
          parsed.forEach((p: any) => {
            if (p && p.id && !isDemoParteIdApp(p.id)) {
              recuperati.set(p.id, p);
            }
          });
        }
      }
      // Recupera eventuali articoli finiti nella chiave dotazioni (CROCE_ORO_MAGAZZINO_MEZZI) nelle build precedenti
      const savedDotazioni = localStorage.getItem('CROCE_ORO_MAGAZZINO_MEZZI');
      if (savedDotazioni) {
        const parsedDot = JSON.parse(savedDotazioni);
        if (Array.isArray(parsedDot)) {
          parsedDot.forEach((p: any) => {
            if (p && p.id && !isDemoParteIdApp(p.id) && isArticoloMagazzinoParti(p) && !recuperati.has(p.id)) {
              recuperati.set(p.id, p);
            }
          });
        }
      }
      return Array.from(recuperati.values());
    } catch {}
    return [];
  });
  const magazzinoPartiRef = useRef<ArticoloMagazzinoMezzi[]>(magazzinoParti);
  useEffect(() => {
    magazzinoPartiRef.current = magazzinoParti;
  }, [magazzinoParti]);
