  const [formUrgenza, setFormUrgenza] = useState<'ROSSO' | 'GIALLO' | 'VERDE' | 'BIANCO'>('ROSSO');
  const [formChiamante, setFormChiamante] = useState('');
  const [formTelefono, setFormTelefono] = useState('');
  const [formEnteIstituzionale, setFormEnteIstituzionale] = useState<EnteIstituzionaleChiamante | null>(null);
  const [erroreChiamante, setErroreChiamante] = useState<string | null>(null);
  const [formIndirizzo, setFormIndirizzo] = useState('Marina di Massa, Viale Vespucci 12');
  const [formDestinazione, setFormDestinazione] = useState('');
  const [formIsStrutturaVeterinaria, setFormIsStrutturaVeterinaria] = useState<boolean>(false);
  const [formIsStrutturaVeterinariaPartenza, setFormIsStrutturaVeterinariaPartenza] = useState<boolean>(false);

  // Indirizzamento specifico del servizio a volontari selezionati (max 3)
  const [formDestinatariVolontari, setFormDestinatariVolontari] = useState<string[]>([]);
  const handleToggleDestinatarioVolontario = (volontarioId: string) => {
    setFormDestinatariVolontari(prev => {
      if (prev.includes(volontarioId)) {
        return prev.filter(id => id !== volontarioId);
      }
      if (prev.length >= 3) {
        return prev;
      }
      return [...prev, volontarioId];
    });
  };

  // Toggle selezione caselle Enti Istituzionali / Forze dell'Ordine
  const handleToggleEnteIstituzionale = (ente: EnteIstituzionaleChiamante) => {
    setErroreChiamante(null);
    if (formEnteIstituzionale === ente) {
      // Se già selezionato, deseleziona (ritorna a cittadino privato con dati obbligatori)
      setFormEnteIstituzionale(null);
      if (formChiamante === ente) {
        setFormChiamante('');
      }
      const targetConfig = ENTI_ISTITUZIONALI_CONFIG.find(e => e.id === ente);
      if (formTelefono === targetConfig?.defaultTel) {
        setFormTelefono('');
      }
    } else {
      // Seleziona la casella dell'ente istituzionale (esenzione dalla compilazione altri dati)
      setFormEnteIstituzionale(ente);
      const targetConfig = ENTI_ISTITUZIONALI_CONFIG.find(e => e.id === ente);
      // Se il campo chiamante è vuoto o era il nome di un altro ente istituzionale, imposta il nome dell'ente
      if (!formChiamante.trim() || ENTI_ISTITUZIONALI_CONFIG.some(e => e.id === formChiamante)) {
        setFormChiamante(ente);
      }
      // Se il telefono è vuoto o era il numero di un altro ente, imposta il numero dell'ente
      if (!formTelefono.trim() || ENTI_ISTITUZIONALI_CONFIG.some(e => e.defaultTel === formTelefono)) {
        setFormTelefono(targetConfig?.defaultTel || '112');
      }
    }
  };

  // Rilevamento automatico se l'indirizzo o destinazione indicata dalla Centrale è una Clinica/Ambulatorio/Dottore/Veterinario
  const rilevaSeStrutturaVeterinaria = (dest: string): boolean => {
    if (!dest) return false;
    const lower = dest.toLowerCase();
    return (
      lower.includes('clinica') ||
      lower.includes('ambulatorio') ||
      lower.includes('dott') ||
      lower.includes('dr.') ||
      lower.includes('dr ') ||
      lower.includes('medico') ||
      lower.includes('veterin') ||
      lower.includes('ospedale vet') ||
      STRUTTURE_VETERINARIE.some(s => lower.includes(s.nome.toLowerCase()))
    );
  };

  const [codiceRientroScelto, setCodiceRientroScelto] = useState<string>('1');
  const [modalAvvisoTelefonataAperta, setModalAvvisoTelefonataAperta] = useState<boolean>(false);
  const [destinazioneAvvisata, setDestinazioneAvvisata] = useState<boolean>(false);

  // Sincronizza lo stato delle strutture veterinarie (partenza e destinazione) se la missione attiva le specifica
  useEffect(() => {
    if (missione?.isStrutturaVeterinariaPartenza !== undefined) {
      setFormIsStrutturaVeterinariaPartenza(missione.isStrutturaVeterinariaPartenza);
    } else if (missione?.indirizzo) {
      setFormIsStrutturaVeterinariaPartenza(rilevaSeStrutturaVeterinaria(missione.indirizzo));
    }

    if (missione?.isStrutturaVeterinaria !== undefined) {
      setFormIsStrutturaVeterinaria(missione.isStrutturaVeterinaria);
    } else if (missione?.destinazione) {
      setFormIsStrutturaVeterinaria(rilevaSeStrutturaVeterinaria(missione.destinazione));
    }
  }, [missione?.codice, missione?.isStrutturaVeterinaria, missione?.isStrutturaVeterinariaPartenza, missione?.destinazione, missione?.indirizzo]);

