                      className="flex-1 md:flex-none py-2.5 px-3.5 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-black text-xs uppercase flex items-center justify-center gap-1.5 shadow-lg active:scale-95 transition-transform"
